package com.mimtrix.libroenoc

/** Borradores provisionales offline de capítulos 96–108. */
object LaterEnocContent96_108 {
    val chapters: List<ChapterEntry> = listOf(
        ChapterEntry(96, "Esperanza para los justos y ayes contra los poderosos", "Paráfrasis provisional original por versículo · cotejo crítico pendiente",
            "La esperanza para quienes sufren se contrapone a la riqueza ostentosa y al poder que se usan para humillar; las obras injustas quedan como memoria y testimonio.",
            "Fuente de trabajo: R. H. Charles, The Book of Enoch (SPCK, 1917), cap. XCVI, transcripción digital Wikisource y control Fish the Right. Charles imprime 96:2 completo entre corchetes como suplemento editorial; se resume aparte y no se integra al núcleo. No se identificó testimonio directo de 4Q212 ni del papyrus griego Chester Beatty-Michigan para 96 en los mapeos consultados. No se inspeccionaron manuscritos. Ver docs/auditoria_96-100_fuentes.md y docs/chapters/96_capitulo_96_parafrasis.md. Ilustración: assets/illustrations/chapter_96.svg, concepto vectorial actual; arte generado específico pendiente.",
            listOf(
                VerseEntry("96:1", "Se anima a los justos a mantener la esperanza: la prosperidad de los pecadores no durará y el texto anuncia una inversión de su dominio. La frase sobre ejercer señorío se conserva como expectativa de vindicación dentro de la visión, no como programa político actual."),
                VerseEntry("96:2", "Suplemento entre corchetes en Charles: los hijos de los justos se elevan como águilas, su nido queda en lo alto y encuentran refugio en hendiduras de la tierra y grietas de las rocas, mientras los adversarios lamentan. Se registra aparte y no se presenta como parte segura del núcleo."),
                VerseEntry("96:3", "Quienes padecieron injusticia reciben la exhortación de no temer. Se les promete curación, una luz brillante y una voz de descanso procedente del cielo."),
                VerseEntry("96:4", "Se denuncia a quienes usan su riqueza para parecer justos, aunque su propia conciencia los acusa. Sus actos quedan como testimonio y memoria de su maldad."),
                VerseEntry("96:5", "Se reprende a quienes consumen los mejores alimentos y beben en exceso mientras usan su poder para aplastar a los humildes."),
                VerseEntry("96:6", "El pasaje censura a quienes beben de cualquier fuente pero han abandonado la fuente de vida; anuncia que se consumirán y marchitarán repentinamente. No se impone una interpretación alegórica única."),
                VerseEntry("96:7", "Las prácticas injustas, el fraude y la blasfemia quedarán registradas como testimonio adverso contra quienes las realizan."),
                VerseEntry("96:8", "Se denuncia a los fuertes que emplean su fuerza para oprimir a los justos. El texto anuncia su destrucción y contrapone ese destino con días buenos para los justos en el tiempo del juicio.")
            )),        ChapterEntry(97, "La vindicación de los justos y la riqueza injusta", "Paráfrasis provisional original por unidades numeradas · cotejo crítico pendiente",
            "El texto primero anima a los justos, después confronta a los pecadores con el juicio y termina denunciando la riqueza adquirida sin justicia.",
            "Fuente de trabajo: R. H. Charles, The Book of Enoch (SPCK, 1917), cap. XCVII; The Book and Me, transcripción de Charles 1917; Loren T. Stuckenbruck, 1 Enoch 91–108 (2007), esquema y notas de 97:1–10, pp. 318–325. El papyrus griego Chester Beatty–Michigan XII comienza en medio de 97:6, con lagunas y lecturas difíciles; no cubre 97:1–5. En 97:8a el griego coincide en lo esencial con la idea de riqueza no adquirida por justicia, aunque cambia la construcción; en 97:9d–e la numeración de Charles 1917 difiere de algunas transcripciones de 1912; es una diferencia editorial, no una variante manuscrita demostrada. La lectura etiópica de 97:9 sobre trabajadores del campo difiere del griego, que ofrece una lectura equivalente a bienes; 97:10 también difiere en el sujeto de la imagen del agua. No se armonizan ni reconstruyen estas formas. No se inspeccionaron fotos de manuscritos ni el aparato completo de Bonner. Ilustración generada específica: assets/illustrations/chapter_97_generated.svg; SVG de 128×192 con raster embebido 64×96, no master de impresión. Ver docs/chapters/97_capitulo_97_parafrasis.md y docs/auditoria_96-100_fuentes.md.",
            listOf(
                VerseEntry("97:1", "Se anima a los justos a confiar en que la vergüenza y la ruina alcanzarán a quienes practican la injusticia cuando llegue el día del juicio."),
                VerseEntry("97:2", "A los pecadores se les advierte que el Altísimo no ha olvidado el daño que hacen y que el juicio contra ellos será motivo de vindicación para los justos. Charles menciona también la reacción de los ángeles celestiales."),
                VerseEntry("97:3", "Se pregunta a los pecadores qué harán y adónde podrán huir cuando llegue el juicio y se oiga la oración de quienes padecieron injustamente."),
                VerseEntry("97:4", "Se anuncia que serán considerados junto con quienes eligieron asociarse a los pecadores. La frase funciona como testimonio contra esa alianza; no identifica aquí a personas concretas."),
                VerseEntry("97:5", "La oración de los justos llegará al Señor. Para quienes los oprimieron comenzará el tiempo de rendir cuentas."),
                VerseEntry("97:6", "Las palabras y obras injustas quedarán expuestas ante el Santo Grande. Los culpables sentirán vergüenza y sus obras, por estar fundadas en la injusticia, serán rechazadas."),
                VerseEntry("97:7", "Se pronuncia un ay contra los pecadores que habitan tanto en el mar como en tierra firme: ni la distancia ni el lugar los sustraen del recuerdo adverso de sus actos."),
                VerseEntry("97:8a", "El reproche se dirige a quienes obtienen plata y oro sin justicia. La denuncia apunta a la adquisición injusta y al abuso de la riqueza, no a toda posesión en abstracto."),
                VerseEntry("97:8b", "El autor pone en boca de los ricos una declaración jactanciosa: se consideran prósperos, dueños de cuanto desean y seguros por la abundancia reunida. Es un discurso atribuido a los adversarios, no una aprobación del narrador."),
                VerseEntry("97:9a–9c", "Los ricos continúan hablando como si sus planes y reservas les garantizaran el futuro: han acumulado plata y creen que pueden hacer cuanto se propongan."),
                VerseEntry("97:9d", "La lectura etiópica impresa por Charles menciona numerosos trabajadores del campo en sus casas. La imagen y su relación con la frase siguiente son difíciles; no se fuerza una interpretación más concreta."),
                VerseEntry("97:9e", "Se describe la abundancia de los graneros mediante una comparación con el agua. La relación exacta entre esta cláusula y la anterior varía en la transmisión."),
                VerseEntry("97:10", "La respuesta deshace la jactancia: la riqueza obtenida injustamente no permanecerá y desaparecerá con rapidez. Los poseedores serán entregados a una gran maldición. La imagen del agua presenta diferencias entre las formas etiópica y griega, por lo que no se decide una reconstrucción única.")
            )),
        ChapterEntry(98, "La responsabilidad humana y el registro de las obras", "Paráfrasis provisional por versículo · cotejo crítico pendiente",
            "El capítulo vincula el lujo sin sabiduría, la responsabilidad humana por el pecado y la certeza de que la opresión queda registrada ante el Altísimo.",
            "Fuente de trabajo: R. H. Charles, The Book of Enoch (SPCK, 1917), cap. XCVIII; transcripción The Book and Me; Loren T. Stuckenbruck, 1 Enoch 91–108 (2007), discusión de 98:1–3 y notas textuales, pp. 325–329. El papyrus griego Chester Beatty–Michigan XII presenta lagunas en 98:3b–4a y 98:11b–12a por rotura y omite 98:15 por salto de texto. En 98:1, el griego y algunos manuscritos etiópicos dicen “a los sabios y no a los necios”, frente a la lectura etiópica “a los sabios y a los necios”. En 98:2–3 difieren persona gramatical, lista de bienes y explicación de la pérdida de sabiduría. No se armonizan las tradiciones ni se rellena el griego. No se inspeccionaron fotos ni el aparato completo de Bonner. Ver docs/chapters/98_capitulo_98_parafrasis.md y docs/auditoria_96-100_fuentes.md. Ilustración: assets/illustrations/chapter_98.svg, concepto específico de registro de obras, lujo y juicio; refinamiento artístico pendiente.",
            listOf(
                VerseEntry("98:1", "Enoc introduce un juramento dirigido a quienes poseen sabiduría y también a los necios, anunciando que todos verán acontecimientos numerosos y difíciles sobre la tierra."),
                VerseEntry("98:2", "Se describe a hombres que exhiben adornos, colores, vestiduras costosas, poder y abundancia de plata y oro. El lujo se presenta como desmesurado y como una riqueza que se derrama en exceso. La forma griega organiza la frase de manera distinta y relaciona la plata y el oro con el alimento y con las casas."),
                VerseEntry("98:3", "La abundancia no conduce a sabiduría: el texto anuncia que quienes se apoyan en ella quedarán privados de instrucción y entendimiento, y perderán junto con sus posesiones el honor y el esplendor. La imagen final es la de espíritus arrojados a un horno de fuego, en medio de vergüenza, matanza y gran pobreza. La relación causal varía entre las formas etiópica y griega."),
                VerseEntry("98:4", "En un juramento dirigido a los pecadores, Enoc afirma que el pecado no fue enviado a la tierra como una fuerza impuesta desde fuera: el ser humano lo produjo por sus propias decisiones. Quienes lo practican quedan bajo una gran maldición."),
                VerseEntry("98:5", "El texto añade que la esterilidad no fue impuesta a la mujer como una orden externa, sino que vincula la muerte sin descendencia con las obras de sus propias manos. La formulación es difícil y no debe convertirse en una afirmación médica ni en una regla general sobre las mujeres."),
                VerseEntry("98:6", "Enoc jura por el Santo Grande que las malas acciones de los pecadores están expuestas en los cielos y que ninguna de sus obras de opresión permanece escondida."),
                VerseEntry("98:7", "Se les advierte que no se engañen pensando que sus actos pasan inadvertidos: cada pecado queda registrado día tras día ante el Altísimo."),
                VerseEntry("98:8", "La opresión que ejercen también queda escrita y se conserva como registro hasta el día del juicio."),
                VerseEntry("98:9", "Se pronuncia un ay contra los necios: su propia insensatez los conduce a la ruina, porque se rebelan contra quienes poseen sabiduría y no alcanzarán el bien que esperan."),
                VerseEntry("98:10", "Se les recuerda que están encaminados al día de la destrucción. No deben confiar en prolongar su vida ni en hallar rescate; el texto los presenta preparados para el gran juicio, la tribulación y la vergüenza."),
                VerseEntry("98:11", "Otro ay se dirige a quienes endurecen el corazón, practican el mal y “comen sangre”. El pasaje les pregunta de dónde obtienen el alimento y la bebida que los sacian, y responde que proceden de los bienes que el Señor Altísimo distribuyó abundantemente sobre la tierra. A pesar de recibir esos bienes, no tendrán paz."),
                VerseEntry("98:12", "Se denuncia a quienes aman las obras de injusticia y, aun así, esperan recibir el bien. El pasaje anuncia que serán entregados a la mano de los justos para sufrir el juicio que merecen; la imagen de ejecución se mantiene como lenguaje de condena escatológica."),
                VerseEntry("98:13", "Se pronuncia un ay contra quienes se alegran por la aflicción de los justos: el texto anuncia que no tendrán sepultura."),
                VerseEntry("98:14", "Se reprende a quienes desprecian o invalidan las palabras de los justos; para ellos no habrá esperanza de vida."),
                VerseEntry("98:15", "Se condena a quienes escriben palabras falsas e impías para que otros las oigan y, siguiendo su influencia, actúen mal contra sus vecinos."),
                VerseEntry("98:16", "La sección concluye declarando que esos malvados no tendrán paz y morirán de manera repentina.")
            )),
        ChapterEntry(99, "Advertencias contra la idolatría y la opresión", "Paráfrasis provisional · cotejo crítico pendiente",
            "La justicia se expresa en la conducta y en el cuidado del prójimo; el capítulo denuncia la falsedad, la idolatría, el abandono, la explotación y la opresión.",
            "Numeración de Charles 1917: 16 versículos. Estructura: 99:1–2 cierra los ayes de 98:9–99:2; 99:3–5 exhorta a los justos; 99:6–9 advierte contra idolatría y extravío; 99:10 bendice a quienes reciben sabiduría; 99:11–16 denuncia daños al prójimo y explotación. En 99:1 hay variantes etiópicas de segunda/tercera persona. En 99:2, Ge'ez transmite ley eterna y el griego alianza eterna; también difiere la frase sobre quienes se consideran sin pecado. 99:5 se mantiene sin inventar causa social. En 99:6–9 no se resuelve el antecedente de la expresión sobre las visiones. Stuckenbruck indica que el manuscrito griego Chester Beatty–Michigan no conserva 99:11–12; no se reconstruyen esos versículos desde el griego. En 99:12 se enfrentan la lectura de medidas falsas de Charles y la formulación etiópica sobre el fundamento del pecado/engaño. En 99:14 varían medida/fundamento y ley/alianza. En 99:16 hay variantes de persona y pronombres. Fuentes: Charles, The Book of Enoch (1917), cap. XCIX; Stuckenbruck, 1 Enoch 91–108 (2007), pp. 357–371 y 415–416. Se consultaron transcripciones y comentario, no fotografías ni aparatos completos; paráfrasis original, no traducción literal. Ilustración offline: assets/illustrations/chapter_99.svg; el concepto vectorial previo se conserva por separado.",
            listOf(
                VerseEntry("99:1", "Se pronuncia un ay contra quienes practican acciones perversas y celebran y ensalzan palabras falsas; esa conducta no conduce a una vida buena."),
                VerseEntry("99:2", "Se reprende a quienes alteran las palabras de verdad, quebrantan la ley o alianza eterna y se presentan como si no fueran pecadores. El cierre anuncia su humillación y caída."),
                VerseEntry("99:3", "Se exhorta a los justos a preparar sus oraciones como memoria y testimonio ante los ángeles, para que la culpa de los pecadores sea presentada ante el Altísimo."),
                VerseEntry("99:4", "Se anuncia que, en aquellos días, las naciones serán agitadas y sus grupos familiares se levantarán en el tiempo de la destrucción."),
                VerseEntry("99:5", "El texto describe a personas necesitadas que se llevan a sus hijos y luego los abandonan, incluso cuando todavía son lactantes; la narración subraya la falta de compasión, sin explicar las circunstancias."),
                VerseEntry("99:6", "El narrador vuelve a jurar a los pecadores que el pecado está dispuesto para un día de derramamiento de sangre que no cesará."),
                VerseEntry("99:7", "Se condena a quienes rinden culto a piedras e imágenes labradas de oro, plata, madera, piedra o barro, y a quienes siguen espíritus impuros, demonios e ídolos sin conocimiento; esas prácticas no les darán ayuda."),
                VerseEntry("99:8", "La insensatez interior los conduce al extravío: el temor que nace en su corazón y las visiones de los sueños aparecen asociados con el oscurecimiento de su mirada."),
                VerseEntry("99:9", "El pasaje relaciona ese extravío con el temor, las obras realizadas en falsedad y la adoración de una piedra; anuncia que su ruina llegará de manera repentina. El antecedente de la expresión estas cosas queda abierto."),
                VerseEntry("99:10", "Se declara dichosos a quienes reciben y comprenden las palabras de sabiduría, siguen los caminos del Altísimo y no se unen a los impíos; se les anuncia salvación."),
                VerseEntry("99:11", "Se pronuncia un ay contra quienes difunden el mal entre sus vecinos; el texto anuncia para ellos una muerte en el Seol."),
                VerseEntry("99:12", "Se denuncia a quienes falsean las medidas y provocan amargura en la tierra. La formulación también se relaciona en la tradición etiópica con un fundamento de pecado y engaño."),
                VerseEntry("99:13", "Se reprende a quienes levantan sus casas mediante el trabajo penoso de otras personas y emplean como materiales simbólicos el pecado y la injusticia; no tendrán paz."),
                VerseEntry("99:14", "Se condena a quienes rechazan la medida o fundamento recibido y la herencia duradera de sus padres, y siguen el espíritu del error; no hallarán descanso."),
                VerseEntry("99:15", "Se pronuncia un ay contra quienes practican la injusticia, sostienen la opresión y asesinan a sus vecinos mientras se acerca el día del gran juicio."),
                VerseEntry("99:16", "Se anuncia la caída de la gloria de los culpables, la aflicción de su interior y la ejecución del juicio; los santos y justos recordarán sus pecados.")
            )),
        ChapterEntry(100, "La violencia, la custodia de los justos y el testimonio de la creación", "Paráfrasis provisional original por los 13 versículos de Charles 1917 · cotejo crítico pendiente",
            "La violencia destruye los vínculos humanos; el juicio alcanza a los perseguidores, los justos reciben guardianes y la creación aparece como testigo de la injusticia.",
            "Fuente base: R. H. Charles, The Book of Enoch (SPCK, 1917), cap. C, transcripción Fish the Right controlada con el escaneo de la edición. Stuckenbruck, 1 Enoch 91–108 (2007), vista previa introductoria p. 17: el papiro griego Chester Beatty–Michigan XII se asigna al tramo 97:6–104:13, que abarca el cap. 100, pero no se infiere preservación continua de cada verso. El mapa resumido de 4Q212 llega a 94:1–2 y el de 4Q204 a 104:13–105:2 y material de Noé; no se asigna fragmento arameo directo a 100 en esa lista. No se inspeccionaron fotografías ni aparato crítico y no se afirman variantes específicas. Ver docs/chapters/100_capitulo_100_parafrasis.md y docs/auditoria_96-100_fuentes.md. Ilustración generada: assets/illustrations/chapter_100.svg (preview 128×192); concepto vectorial previo conservado por separado; master de impresión pendiente.",
            listOf(
                VerseEntry("100:1", "Se anuncia que padres e hijos caerán juntos y que hermanos se darán muerte unos a otros; la sangre es comparada con corrientes que cubren el lugar."),
                VerseEntry("100:2", "La hostilidad alcanzará a hijos y nietos, y el pecador tampoco respetará al hermano que debería honrar. La matanza se prolongará desde el amanecer hasta el ocaso."),
                VerseEntry("100:3", "En una imagen hiperbólica, los caballos avanzan hasta quedar sumergidos a la altura del pecho y los carros quedan cubiertos por la sangre de los pecadores; no se ofrece una cifra ni una descripción militar verificable."),
                VerseEntry("100:4", "Los ángeles descenderán a los lugares ocultos y reunirán a quienes hicieron descender o propagaron el pecado; el Altísimo se levantará para ejecutar juicio contra los pecadores."),
                VerseEntry("100:5", "Los justos y santos recibirán guardianes escogidos entre los ángeles, que los protegerán con cuidado extremo hasta que terminen la maldad y el pecado. Aunque duerman un sueño prolongado, no tendrán que vivir con temor."),
                VerseEntry("100:6", "Los habitantes de la tierra verán a los sabios en seguridad, comprenderán las palabras del libro y reconocerán que las riquezas no podrán rescatarlos de las consecuencias de sus pecados."),
                VerseEntry("100:7", "Se pronuncia un ay contra quienes hacen sufrir a los justos y los queman con fuego: recibirán una respuesta correspondiente a sus propias obras."),
                VerseEntry("100:8", "Otro ay se dirige a quienes endurecen el corazón y permanecen atentos para planear el mal; el temor los alcanzará y no encontrarán quien los socorra."),
                VerseEntry("100:9", "Se anuncia un ay por las palabras y acciones impías; la sentencia se expresa mediante la imagen de llamas abrasadoras, más terribles que el fuego conocido."),
                VerseEntry("100:10", "Las obras serán examinadas en el ámbito celestial: el Altísimo pedirá testimonio a los ángeles, al sol, a la luna y a las estrellas acerca de quienes ejercieron juicio injusto contra los rectos en la tierra."),
                VerseEntry("100:11", "Las nubes, la neblina, el rocío y la lluvia serán convocados como testigos; el pasaje dice que serán retenidos y que su ausencia recordará a los culpables sus pecados."),
                VerseEntry("100:12", "Con tono irónico, se invita a ofrecer regalos a la lluvia y al rocío para que desciendan; ni el oro ni la plata pueden comprar el favor de las aguas."),
                VerseEntry("100:13", "Cuando lleguen la escarcha, la nieve y las tormentas de nieve con su frío y calamidades, los culpables no podrán mantenerse en pie ante ellas.")
            )),
        ChapterEntry(101, "El temor de la creación y la falta de temor humano", "Paráfrasis provisional · cotejo crítico pendiente",
            "la naturaleza reconoce sus límites, mientras el ser humano es exhortado a reconocer al Creador y a abandonar el mal.",
            "Fuente: R. H. Charles, The Book of Enoch (1912), cap. CI, https://rojc.uk/book-of-enoch.htm (consultado 19-11-2026). Paráfrasis original. Pendiente: cotejar el capítulo con la edición base y revisar las imágenes del mar, la lluvia y los navegantes. Ilustración: assets/illustrations/chapter_101.svg — barco antiguo entre olas, mar encuadrado por una costa y un cielo que recuerda el límite del agua.",
            listOf(VerseEntry("Capítulo 101 · paráfrasis", "Enoc pide a sus hijos observar el cielo y las obras del Altísimo y vivir sin maldad. Recuerda que la lluvia y el rocío pueden ser retenidos, y que los navegantes temen a las olas porque sus bienes y sus vidas están en peligro. El mar y sus movimientos tienen límites puestos por el Creador. En contraste, quienes pecan en la tierra no muestran temor ni reconocen al que hizo el cielo, la tierra y las criaturas."))),
        ChapterEntry(102, "El terror del juicio y la esperanza de los muertos justos", "Paráfrasis provisional · cotejo crítico pendiente",
            "la apariencia de igualdad entre la muerte de justos e injustos no es el final; el texto sostiene una esperanza de juicio y vindicación.",
            "Fuente: R. H. Charles, The Book of Enoch (1912), cap. CII, https://rojc.uk/book-of-enoch.htm (consultado 19-11-2026). Paráfrasis original. Pendiente: cotejar vocabulario sobre Sheol, espíritus y muerte, y las lecturas problemáticas del capítulo. Ilustración: assets/illustrations/chapter_102.svg — un cielo estremecido sobre una caverna oscura; pequeñas luces rodean a los justos mientras una llama de juicio ilumina el horizonte.",
            listOf(VerseEntry("Capítulo 102 · paráfrasis", "La visión anuncia un fuego terrible y un juicio ante el cual los luminares y la tierra tiemblan. Los pecadores son descritos como incapaces de hallar refugio, mientras los justos que murieron en rectitud reciben una exhortación a no desesperar: su descenso al lugar de los muertos y su sufrimiento no significan que hayan sido olvidados. Los injustos se burlan de ellos, comparando ambas muertes, pero Enoc les responde con una advertencia sobre el juicio que espera a quienes roban, pecan y se aprovechan de los demás."))),
        ChapterEntry(103, "Los destinos distintos y el lamento de los justos", "Paráfrasis provisional · cotejo crítico pendiente",
            "la prosperidad visible no define el destino final; el sufrimiento del justo queda registrado y no es olvidado.",
            "Fuente: R. H. Charles, The Book of Enoch (1912), cap. CIII, https://rojc.uk/book-of-enoch.htm (consultado 19-11-2026). Paráfrasis original. Pendiente: revisar la división de los versos, las quejas atribuidas a los justos y su relación con el capítulo siguiente; cotejo crítico pendiente. Ilustración: assets/illustrations/chapter_103.svg — dos libros abiertos: uno con luz y nombres preservados, otro con páginas oscuras; una figura humilde mira hacia el cielo.",
            listOf(VerseEntry("Capítulo 103 · paráfrasis", "Enoc afirma haber leído las tablas celestiales: para los que murieron en justicia están preparados el bien, la alegría y la gloria; su memoria permanece y su recompensa supera la de los vivos. Los pecadores, aunque hayan muerto en riqueza y aparente prosperidad, son destinados a tribulación y juicio. La visión también reproduce la queja de los justos que sufrieron en vida: trabajaron, padecieron, fueron pocos, sometidos y sin ayuda, y sus opresores no escucharon sus reclamos ni cesaron de dispersarlos."))),
        ChapterEntry(104, "Consuelo, memoria y advertencia a quienes falsifican", "Paráfrasis provisional · cotejo crítico pendiente",
            "los justos son recordados y la transmisión fiel de la sabiduría importa; el texto advierte contra falsificar las palabras.",
            "Fuente: R. H. Charles, The Book of Enoch (1912), cap. CIV, https://rojc.uk/book-of-enoch.htm (consultado 19-11-2026). Paráfrasis original. Pendiente: cotejar las admoniciones contra falsificadores, los pasajes sobre libros y las variantes de transmisión. Ilustración: assets/illustrations/chapter_104.svg — un ángel sostiene un libro con nombres que brillan; detrás, un rollo deformado se oscurece y se contrasta con otro copiado con cuidado.",
            listOf(VerseEntry("Capítulo 104 · paráfrasis", "Enoc consuela a los justos: los ángeles los recuerdan, sus nombres están escritos ante el Grande y su vergüenza se transformará en luz. Les pide conservar la esperanza y no unirse a la violencia de los pecadores. A continuación denuncia a quienes creen que sus actos no serán registrados, a quienes mienten o alteran las palabras de rectitud y escriben falsedades. La visión afirma que los escritos verdaderos, transmitidos sin distorsión, serán entregados a los sabios y justos para su alegría, conocimiento y recompensa."))),
        ChapterEntry(105, "La unión del Señor y su hijo con los justos", "Paráfrasis provisional · cotejo crítico pendiente",
            "la conclusión anuncia comunión y paz duraderas para quienes caminan en justicia.",
            "Fuente: R. H. Charles, The Book of Enoch (1912), cap. CV, https://rojc.uk/book-of-enoch.htm (consultado 19-11-2026). Paráfrasis original. Pendiente: Cotejo contra texto base pendiente. Ilustración: assets/illustrations/chapter_105.svg — un grupo de justos reunido bajo una luz celestial, con dos figuras simbólicas en el horizonte; una senda de paz conduce hacia ellas.",
            listOf(VerseEntry("Capítulo 105 · paráfrasis", "La voz divina ordena que se convoque a los hijos de la tierra para mostrarles la sabiduría y el testimonio. Se describe a los justos como guiados y recompensados. La declaración final anuncia que el Señor y su hijo estarán unidos con ellos para siempre en los caminos de rectitud y que habrá paz. La breve sección cierra con una bendición."))),
        ChapterEntry(106, "El nacimiento extraordinario de Noé", "Paráfrasis provisional por rangos · cotejo crítico pendiente",
            "Nacimiento noánico en cuatro unidades narrativas. La ilustración generada para este capítulo se muestra como preview offline desde assets/illustrations/chapter_106_generated.svg; el concepto vectorial anterior se conserva.",
            "Fuente de trabajo: R. H. Charles, SPCK 1917, Project Gutenberg #77935. Testigos fragmentarios reportados: 4Q204 (104:13–106:2 y 106:13–107:2), Greek Chester Beatty–Michigan XII (106:1–107:3), Latin Royal Ms. 5 E XIII (106:1–18). Los rangos son bibliográficos, no cotejo directo. Genesis Apocryphon 1Q20 y 4Q534–536 son paralelos relacionados, no copias. Pendiente cotejo de fotos/aparato; no armonizar variantes ni reconstruir lagunas.",
            listOf(
                VerseEntry("106:1–3", "Lamech y su esposa tienen un hijo de apariencia extraordinaria: cuerpo claro y rojizo, cabello muy blanco y ojos luminosos; al abrirlos, parece iluminar la casa. La partera lo levanta y el niño abre la boca; las versiones de la frase sobre su voz o discurso deben cotejarse."),
                VerseEntry("106:4–7", "Lamech se asusta por el aspecto del recién nacido y teme que sea semejante a los seres celestiales. Acude a Matusalén y le pide consultar a Enoc para conocer la verdad."),
                VerseEntry("106:8–12", "Matusalén repite el relato de Lamech y la apariencia del niño, y solicita una explicación. El pasaje vuelve a describir que el niño abre la boca y bendice al Señor del cielo."),
                VerseEntry("106:13–19", "Enoc vincula el nacimiento con la transgresión de los Vigilantes, los gigantes y el castigo que limpiará la tierra. Anuncia el diluvio y la supervivencia de Noé y sus hijos, y advierte que la injusticia volverá a crecer después de la primera destrucción.")
            )),
        ChapterEntry(107, "La generación justa y la misión de Noé", "Paráfrasis provisional por unidades · cotejo crítico pendiente",
            "Cierre de la unidad Nacimiento de Noé (106:1–107:3).",
            "Fuente de trabajo: Charles 1917, Project Gutenberg #77935. Testigos parciales reportados: 4Q204 106:13–107:2 y Greek Chester Beatty–Michigan XII 106:1–107:3; la asignación aramea no cubre 107:3. No se cotejaron fotos ni aparato. El nombre/etimología Noé y el consuelo son provisionales.",
            listOf(
                VerseEntry("107:1", "Las tablas anuncian generaciones que seguirán transgrediendo hasta que surja una generación justa; entonces la transgresión será destruida, el pecado desaparecerá de la tierra y el bien volverá."),
                VerseEntry("107:2", "Enoc pide a Matusalén que comunique a Lamech que el niño es realmente su hijo y que su sospecha no tiene fundamento."),
                VerseEntry("107:3", "Matusalén regresa y transmite la revelación; el niño recibe el nombre de Noé, relacionado en el relato con el consuelo de la tierra después de la destrucción.")
            )),
        ChapterEntry(108, "La admonición escatológica", "Paráfrasis provisional por rangos · cotejo crítico pendiente",
            "Unidad final separada: juicio de los pecadores y recompensa de los fieles. No debe confundirse con el Nacimiento de Noé.",
            "Fuente de trabajo: Charles SPCK 1917, Project Gutenberg #77935 y Open Scroll 1 Enoch 108. 108 se conserva solo en Ge'ez según los testigos consultados; no se identifica testimonio Aramaic/Greek/Coptic/Latin. Stuckenbruck y un estudio de Edinburgh describen su carácter de apéndice y proponen una datación posterior (hipótesis, no certeza). No se cotejó Ge'ez directamente; no atribuirlo a Qumrán.",
            listOf(
                VerseEntry("108:1–3", "Enoc presenta otro libro para Matusalén y quienes guardarán la ley al final. Los justos deben esperar el fin de la maldad; los nombres de los transgresores serán borrados de los libros, y su descendencia y espíritus recibirán juicio en un lugar desolado y de fuego."),
                VerseEntry("108:4–6", "Enoc ve una profundidad semejante a una nube invisible, fuego y formas luminosas que se mueven como montañas. Un ángel explica que es el lugar destinado a pecadores, blasfemos y quienes pervierten lo anunciado por el Señor."),
                VerseEntry("108:7–10", "La visión recuerda a los humildes que fueron afligidos, despreciaron la riqueza, soportaron tortura y vergüenza y conservaron su fidelidad. Su sufrimiento y recompensa se recuerdan en los libros."),
                VerseEntry("108:11–15", "Los espíritus fieles serán transformados y llevados a la luz; recibirán asientos de honor y resplandecerán. Los pecadores contemplarán ese destino y marcharán al lugar y tiempo que les corresponden.")
            ))
    )
}
